params.code:
// Deep space with a faint fixed starfield, and a fine grid in the Earth-Moon
// plane, centred on Earth: 10,000 and 100,000 km lines that fade in by their
// spacing on screen. u0 zoom, u1 u2 camera centre, u3 roll, u4 elevation (rad),
// u5 grid opacity.
float hash2(float2 p) { return frac(sin(dot(p, float2(127.1, 311.7))) * 43758.5453); }
float gridLine(float v, float step, float px) {
  float d = abs(frac(v / step + 0.5) - 0.5) * step;
  return saturate(1.0 - d / px);
}
float stars(float2 pos) {
  float s = 0.0;
  for (int l = 0; l < 2; l++) {
    float cell = l == 0 ? 9.0 : 23.0;
    float2 c = floor(pos / cell);
    float h = hash2(c + float(l) * 17.3);
    if (h > (l == 0 ? 0.985 : 0.955)) {
      float2 o = float2(hash2(c + 3.1), hash2(c + 7.7)) * (cell - 2.0) + 1.0;
      float d = length(pos - (c * cell + o));
      float b = pow(hash2(c + 11.0), 3.0) * (l == 0 ? 0.35 : 0.75) + 0.05;
      s += b * exp(-d * d / (l == 0 ? 0.45 : 0.8));
    }
  }
  return s;
}
float4 shade(float2 pos, float px) {
  float2 sz = size();
  float2 uv = pos / sz;
  float r = length((uv - float2(0.52, 0.47)) * float2(1.0, 0.62));
  float3 bg = lerp(float3(0.0095, 0.0130, 0.0235), float3(0.0016, 0.0022, 0.0042), smoothstep(0.0, 0.78, r));
  bg += float3(0.62, 0.68, 0.80) * stars(pos) * 0.11;
  float Z = param(0);
  float cr = cos(param(3)), sr = sin(param(3));
  float2 d0 = pos - sz * 0.5;
  float2 r0 = float2(cr * d0.x + sr * d0.y, -sr * d0.x + cr * d0.y);
  float X = param(1) + r0.x / Z;
  float Y = (param(2) - r0.y / Z) / max(sin(param(4)), 0.2);
  float kp = 1.0 / Z;
  float s1 = 10000.0, s2 = 100000.0;
  float w1 = smoothstep(18.0, 60.0, s1 * Z) * (1.0 - smoothstep(900.0, 2400.0, s1 * Z));
  float w2 = smoothstep(18.0, 60.0, s2 * Z) * (1.0 - smoothstep(900.0, 2400.0, s2 * Z));
  float g = max(max(gridLine(X, s1, kp * 0.9), gridLine(Y, s1, kp * 0.9)) * w1 * 0.5,
                max(gridLine(X, s2, kp * 1.1), gridLine(Y, s2, kp * 1.1)) * w2);
  float3 col = bg + float3(0.018, 0.026, 0.042) * g * param(5);
  return float4(col, 1.0);
}

// Earth and Moon as lit spheres under an orthographic camera that looks down
// on the Earth-Moon plane (rotating frame: x Earth->Moon, z north).
// u0 zoom px/km, u1 u2 camera centre (km, projected), u3 roll (rad),
// u4..u6 sun direction, u7..u10 Earth orientation quaternion (rotating ->
// Earth-fixed), u11 camera elevation (rad), u12 city-light gain, u13 overall gain.
// in0 Earth by day, in1 Earth extras (r lights, g water), in2 Moon color,
// in3 Moon slopes (r east, g north; 0.5 flat).
// To scale whenever they are big enough to see; below 22 px (Earth) and 14 px
// (Moon) of radius they are held at that size, like a map symbol.
static const float DREF = 384400.0;
static const float RE = 6371.0;
static const float RM = 1737.4;
static const float TAU = 6.2831853;

float3 qrot(float4 q, float3 v) {
  float3 t = 2.0 * cross(q.xyz, v);
  return v + q.w * t + cross(q.xyz, t);
}
float2 texPx(float3 n) {
  float lon = atan2(n.y, n.x);
  float lat = asin(clamp(n.z, -1.0, 1.0));
  return float2((lon / TAU + 0.5) * size().x, (0.5 - lat / 3.14159265) * size().y);
}
float enc(float x) { return linear_to_srgb1(max(x, 0.0)); }
float smax6(float a, float b) { return pow(pow(a, 6.0) + pow(b, 6.0), 1.0 / 6.0); }

float3 earthColor(float3 n, float3 V, float3 sun, float4 q) {
  float3 b = qrot(q, n);
  float2 tp = texPx(b);
  float3 day = input(0, tp).rgb;
  float4 aux = input(1, tp);
  float lights = enc(aux.r), water = enc(aux.g);
  float mu = dot(n, sun);
  float lit = smoothstep(-0.06, 0.20, mu);
  float3 col = day * lit * (0.22 + 1.10 * saturate(mu + 0.06));
  // Sun glint on open water.
  float3 h = normalize(sun + V);
  col += float3(1.0, 0.92, 0.78) * pow(saturate(dot(n, h)), 320.0) * 0.55 * water * saturate(mu * 4.0);
  // Night: a faint cool fill so the globe still reads, and the cities.
  float night = 1.0 - smoothstep(-0.16, 0.03, mu);
  col += day * float3(0.45, 0.6, 1.0) * 0.022 * night;
  col += float3(1.0, 0.64, 0.30) * lights * lights * night * param(12);
  // A thin warm band just on the day side of the terminator.
  col += float3(0.50, 0.24, 0.10) * exp(-abs(mu - 0.04) * 34.0) * 0.035 * smoothstep(-0.02, 0.04, mu);
  // Air on the limb: blue where lit, a faint glow on the night limb.
  float limb = pow(1.0 - saturate(dot(n, V)), 2.4);
  col = lerp(col, float3(0.30, 0.52, 0.95) * saturate(mu + 0.25), limb * 0.55 * smoothstep(-0.25, 0.3, mu));
  col += float3(0.06, 0.10, 0.22) * limb * 0.25 * night;
  return col;
}

float3 moonColor(float3 n, float3 V, float3 sun) {
  float3 b = float3(-n.x, -n.y, n.z);          // body frame: x to Earth, z north
  float2 tp = texPx(b);
  float3 alb = input(2, tp).rgb;
  float4 sl = input(3, tp);
  float se = (enc(sl.r) - 0.502) * 0.70, sn = (enc(sl.g) - 0.502) * 0.70;
  float lon = atan2(b.y, b.x), lat = asin(clamp(b.z, -1.0, 1.0));
  float3 east = float3(-sin(lon), cos(lon), 0.0);
  float3 north = float3(-sin(lat) * cos(lon), -sin(lat) * sin(lon), cos(lat));
  float3 pb = normalize(b - 2.2 * (se * east + sn * north));   // relief, exaggerated 2.2x
  float3 p = float3(-pb.x, -pb.y, pb.z);
  float mu0 = dot(p, sun), mu = saturate(dot(n, V));
  float m0 = saturate(mu0);
  // Lunar-Lambert: flat at full phase, Lambert toward the terminator.
  float L = 0.45 * m0 + 0.55 * 2.0 * m0 / (m0 + mu + 1e-3);
  float3 col = alb * L * 1.25 * smoothstep(-0.02, 0.05, mu0 + 0.03);
  // Earthshine on the night side.
  col += alb * 0.03 * saturate(dot(n, float3(-1.0, 0.0, 0.0))) * (1.0 - smoothstep(-0.05, 0.1, mu0));
  return col;
}

float4 bodies(float2 xy, float3 U, float3 V, float3 sun, float4 q, float px, float re, float rm) {
  float rho = length(xy);
  float4 c = float4(0.0);
  if (rho < re * 1.08 + 3.0 * px) {
    float a = saturate((re - rho) / px + 0.5);
    if (a > 0.0) {
      float2 d = xy / re;
      float h = sqrt(saturate(1.0 - dot(d, d)));
      float3 n = float3(d.x, 0.0, 0.0) + d.y * U + h * V;
      c = float4(earthColor(n, V, sun, q) * a, a);
    }
    // Atmosphere just past the limb, lit where the limb is lit.
    float2 dir = xy / max(rho, 1e-3);
    float3 ln = float3(dir.x, 0.0, 0.0) + dir.y * U;
    float glow = exp(-max(rho - re, 0.0) / (re * 0.014 + 1.4 * px)) * smoothstep(-0.35, 0.35, dot(ln, sun));
    float ga = glow * (1.0 - c.a) * 0.6;
    c += float4(float3(0.32, 0.56, 1.0) * ga, ga * 0.6);
  }
  float2 m = xy - float2(DREF, 0.0);
  float rmm = length(m);
  if (rmm < rm + 2.0 * px) {
    float a = saturate((rm - rmm) / px + 0.5);
    if (a > 0.0) {
      float2 d = m / rm;
      float h = sqrt(saturate(1.0 - dot(d, d)));
      float3 n = float3(d.x, 0.0, 0.0) + d.y * U + h * V;
      c = float4(moonColor(n, V, sun) * a, a) + c * (1.0 - a);
    }
  }
  return c;
}

float4 shade(float2 pos, float px) {
  float2 sz = size();
  float Z = param(0);
  float2 cam = float2(param(1), param(2));
  float cr = cos(param(3)), sr = sin(param(3));
  float3 sun = normalize(float3(param(4), param(5), param(6)));
  float4 q = float4(param(7), param(8), param(9), param(10));
  q /= max(length(q), 1e-6);
  float e = param(11);
  float3 U = float3(0.0, sin(e), cos(e));
  float3 V = float3(0.0, -cos(e), sin(e));
  float kmpx = px / Z;
  float re = smax6(RE, 22.0 / Z), rm = smax6(RM, 14.0 / Z);
  float2 d0 = pos - sz * 0.5;
  float2 r0 = float2(cr * d0.x + sr * d0.y, -sr * d0.x + cr * d0.y);
  float2 xy0 = float2(cam.x + r0.x / Z, cam.y - r0.y / Z);
  if (length(xy0) > re * 1.1 + 4.0 * kmpx && length(xy0 - float2(DREF, 0.0)) > rm + 4.0 * kmpx) return float4(0.0);
  int n = (re * Z / px < 260.0 || rm * Z / px < 260.0) ? 4 : 1;
  float4 acc = float4(0.0);
  for (int j = 0; j < n; j++) {
    for (int i = 0; i < n; i++) {
      float2 o = (float2(i, j) + 0.5) / float(n) - 0.5;
      float2 dd = d0 + o * px;
      float2 rr = float2(cr * dd.x + sr * dd.y, -sr * dd.x + cr * dd.y);
      float2 xy = float2(cam.x + rr.x / Z, cam.y - rr.y / Z);
      acc += bodies(xy, U, V, sun, q, n > 1 ? kmpx * 0.35 : kmpx, re, rm);
    }
  }
  return acc / float(n * n) * param(13);
}

float4 shade(float2 pos, float px) {
  float2 p = floor(pos) + floor(time() * 24.0) * float2(37.0, 17.0);
  float h = frac(sin(dot(p, float2(12.9898, 78.233))) * 43758.5453);
  float g = frac(sin(dot(p + 3.1, float2(39.346, 11.135))) * 24634.6345);
  return float4(float3((h + g) * 0.5), 1.0);
}
